"use strict";

const {App} = require("@slack/bolt");

module.exports = function(RED, createApp = options => new App(options)) {
    class SlackNodeError extends Error {}

    function SlackPostNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;
        let app;

        node.on("input", async function(msg, send, done) {
            try {
                const botToken = node.credentials && node.credentials.botToken;
                const signingSecret = node.credentials && node.credentials.signingSecret;
                if (!botToken || !signingSecret) {
                    throw new SlackNodeError("Slack bot token and signing secret are required");
                }
                const destination = RED.util.evaluateNodeProperty(config.destination, config.destinationValueType || "str", node, msg);
                const content = RED.util.evaluateNodeProperty(config.text || "payload", config.textType || "msg", node, msg);
                if (typeof content !== "string" || !content.trim()) {
                    throw new SlackNodeError("Slack content must be a non-empty string");
                }
                if (typeof destination !== "string") {
                    throw new SlackNodeError("Slack recipient must be an ID");
                }
                const id = destination.trim();
                if (config.destinationType === "user" ? !/^[UW][A-Z0-9]+$/.test(id) : !/^[CG][A-Z0-9]+$/.test(id)) {
                    throw new SlackNodeError("Slack recipient must be a valid user or channel ID");
                }
                let filename;
                if (config.sendAs === "markdown") {
                    filename = RED.util.evaluateNodeProperty(config.filename || "message.md", config.filenameType || "str", node, msg);
                    if (typeof filename !== "string" || !/^[^/\\\0\r\n]+\.md$/i.test(filename) || Buffer.byteLength(filename) > 255) {
                        throw new SlackNodeError("Slack Markdown filename must end in .md and contain no path");
                    }
                }

                if (!app) {
                    app = createApp({token: botToken, signingSecret, tokenVerificationEnabled: false});
                }
                let channel = id;
                node.status({fill: "blue", shape: "dot", text: "sending"});
                if (config.destinationType === "user") {
                    const opened = await app.client.conversations.open({users: id});
                    if (!opened.ok || !opened.channel || !opened.channel.id) {
                        throw new SlackNodeError("Slack could not open a direct message");
                    }
                    channel = opened.channel.id;
                }
                if (config.sendAs === "markdown") {
                    const uploaded = await app.client.filesUploadV2({channel_id: channel, filename, content});
                    if (!uploaded.ok || !Array.isArray(uploaded.files) || uploaded.files.some(result => result.ok === false)) {
                        throw new SlackNodeError("Slack did not confirm the file upload");
                    }
                    const file = uploaded.files.flatMap(result => result.files || []).find(item => item.id);
                    if (!file) {
                        throw new SlackNodeError("Slack did not return a file ID");
                    }
                    msg.slack = {channel, fileId: file.id};
                } else {
                    const posted = await app.client.chat.postMessage({channel, text: content});
                    if (!posted.ok || !posted.ts) {
                        throw new SlackNodeError("Slack did not confirm the message");
                    }
                    msg.slack = {channel: posted.channel || channel, ts: posted.ts};
                }
                node.status({fill: "green", shape: "dot", text: "sent"});
                send(msg);
                done();
            } catch (error) {
                node.status({fill: "red", shape: "ring", text: "Slack error"});
                const code = error.data && error.data.error;
                const reason = typeof code === "string" && /^[a-z][a-z0-9_]{0,63}$/.test(code) ? code : null;
                const message = error instanceof SlackNodeError ? error.message : reason ? "Slack request failed: " + reason : "Slack request failed";
                done(new Error(message));
            }
        });
    }

    RED.nodes.registerType("slack post", SlackPostNode, {
        credentials: {
            botToken: {type: "password"},
            signingSecret: {type: "password"}
        }
    });
};
